;WITH SourceRows AS
(
    SELECT
        name,
        display_name,
        active,
        activated_at,
        deactivated_at,
        created_at
    FROM OPENJSON(@DemoTenants)
    WITH
    (
        name NVARCHAR(255) '$.name',
        display_name NVARCHAR(255) '$.display_name',
        active BIT '$.active',
        activated_at DATETIME2 '$.activated_at',
        deactivated_at DATETIME2 '$.deactivated_at',
        created_at DATETIME2 '$.created_at'
    )
)
MERGE crm.tenants AS target
USING SourceRows AS source
    ON target.name = source.name
WHEN MATCHED THEN
    UPDATE SET
        display_name = source.display_name,
        active = source.active,
        activated_at = source.activated_at,
        deactivated_at = source.deactivated_at,
        created_at = source.created_at
WHEN NOT MATCHED BY TARGET THEN
    INSERT
    (
        name,
        display_name,
        active,
        activated_at,
        deactivated_at,
        created_at
    )
    VALUES
    (
        source.name,
        source.display_name,
        source.active,
        source.activated_at,
        source.deactivated_at,
        source.created_at
    );

SET IDENTITY_INSERT crm.sales ON;

